var t=[{title:`Definice`,text:`Antagonistický superset střídá protilehlé pohybové vzorce, například tlak následovaný přítahem. Složená série spojuje dva cviky pro stejnou svalovou skupinu. Okruh může projít pěti stanovišti, než si odpočinete a zopakujete ho. EMOM znamená „každou minutu na minutu“ a AMRAP znamená „co nejvíc kol nebo opakování“ v daném čase.`},{title:`Proč je používat`,text:`Spárování tlaku s přítahem nechá jednu svalovou skupinu pracovat, zatímco druhá odpočívá, což může ušetřit čas. Okruhy mohou na malém prostoru spojit silovou a kardio práci. Mnoho lidí předpokládá, že budují víc síly nebo svalů, ale automaticky to tak není; o tom stále rozhoduje kvalita celkové práce a vaše regenerace.`},{title:`Řiďte únavu`,text:`Těžký dřep spárovaný s náročným mrtvým tahem může zhoršit oba cviky, zejména u začátečníků. Párujte cviky, které si příliš nekonkurují, a odpočívejte dost dlouho, abyste zůstali pod kontrolou. Technické cviky a výbušné skoky často potřebují víc regenerace, než dává časovaný okruh. Supersety používejte, když vám chybí čas a spárování dává smysl pro váš cíl. Nezkracujte odpočinek jen kvůli časovému cíli a okruhy plné skoků nebo složitých pohybů vynechte, pokud je vylučuje váš prostor, omezení hluku nebo tělo.`},{title:`Příklad`,text:`Udělejte deset kontrolovaných kliků s vyvýšením, pak deset podepřených přítahů, pak odpočívejte 90 sekund; opakujte třikrát. Kondiční okruh může použít výstupy na bednu, lehké nošení zátěže a pochodování s plánovaným odpočinkem. Zvolte počet kol, který udržíte, aniž byste se ukvapeně dostali do špatné techniky.`}];var n=[{label:`NSCA: časově úsporný trénink`,url:`https://www.nsca.com/education/articles/ptq/time-efficient-training`},{label:`Stanovisko ACSM z roku 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: bezpečnost a základy silového tréninku`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var a={sections:t,sources:n};export{a as default,t as sections,n as sources};